from collections import deque
import json
R,C=20,25
g=[[2]*C for _ in range(R)]
for r in range(4): g[r][22]=8
for c in range(21,25): g[4][c]=8
for r in (5,6): g[r][21]=8
for c in range(22): g[7][c]=8
for r in (8,9): g[r][21]=8
for c in range(21,25): g[9][c]=8
for r in range(10,20): g[r][22]=8
# flood-fill 2s connected to outside
outside=set(); q=deque()
for r in range(R):
 for c in (0,C-1):
  if g[r][c]==2 and (r,c) not in outside: outside.add((r,c));q.append((r,c))
for c in range(C):
 for r in (0,R-1):
  if g[r][c]==2 and (r,c) not in outside: outside.add((r,c));q.append((r,c))
while q:
 r,c=q.popleft()
 for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
  p=(r+dr,c+dc)
  if 0<=p[0]<R and 0<=p[1]<C and g[p[0]][p[1]]==2 and p not in outside:
   outside.add(p);q.append(p)
trapped=[]
for r in range(R):
 for c in range(C):
  if g[r][c]==2 and (r,c) not in outside:
   g[r][c]=4;trapped.append((r,c))
print('trapped count',len(trapped),'regions')
# connected components fill
unseen=set(trapped)
while unseen:
 start=unseen.pop(); comp={start};q=[start]
 for r,c in q:
  for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
   p=(r+dr,c+dc)
   if p in unseen: unseen.remove(p);comp.add(p);q.append(p)
 print(min(r for r,c in comp),max(r for r,c in comp),min(c for r,c in comp),max(c for r,c in comp),len(comp))
print(json.dumps({'action':'submit','grid':g},separators=(',',':')))

